\underbrace{
\begin{bmatrix}
 0 &amp;amp;1 &amp;amp;0\\
 0 &amp;amp;0 &amp;amp;1\\
 -{k}_{iz} &amp;amp;-{k}_{pz} &amp;amp; -{k}_{dz}
\end{bmatrix}
}_{\mathbf{A}_z}
\mathbf{e}_z 
+
\underbrace{
\begin{bmatrix}
 -{k}_{iz}^{-1}m^{-1}\dot{d}_z\\
